const base=process.env.APP_BASE_URL!,suiteAgent='isolated-sponsor-suite-'+crypto.randomUUID();
const request=(path:string,cookie:string,body?:unknown)=>new Request(new URL(path,base),{method:body?'POST':'GET',headers:{cookie,origin:new URL(base).origin,'Content-Type':'application/json','x-forwarded-for':'198.51.100.123','user-agent':suiteAgent},...(body?{body:JSON.stringify(body)}:{})});
async function fixture(role:string){const email='sponsor-'+crypto.randomUUID()+'@example.invalid';const {user}=await getAuth().api.createUser({body:{email,name:'Fictieve '+role,password:crypto.randomUUID()+crypto.randomUUID()}});await sql`insert into cms_memberships(user_id,role_id) values (${user.id},${role})`;const response=await loginEmail(email);return {...user,cookie:authCookies(response)};}
async function read(cookie:string,portal=false,companyId=''){return workspaceRead(request((portal?'/api/portal/workspace':'/api/cms/sponsor-workspace')+'?mode='+(portal?'portal':'sponsorship')+'&companyId='+companyId,cookie),portal);}
async function command(cookie:string,name:string,args:unknown[],portal=false,companyId='',id=crypto.randomUUID()){
 const state=await read(cookie,portal,companyId);const body={operationId:id,mode:portal?'portal':'sponsorship',companyId,versions:state.versions,commands:[{name,args,offset:0}]};
 return workspaceCommands(request('/api/workspace',cookie,body),body,portal);
}
async function lastMail(subject:string,after:number){const rows=(await readFile('.runtime/mail-sink.jsonl','utf8')).trim().split('\n').filter(Boolean).map(s=>JSON.parse(s));const value=rows.reverse().find(r=>r.subject===subject&&r.at>=after);assert.ok(value,'Real provider sink accepted the message');return value;}
const company=(id:string,ownerId:string):Sponsor=>({id,name:'Fictief Testbedrijf '+id,companyNumber:'12345678',vatNumber:'',address:'Teststraat 1',postalCode:'1234 AB',city:'Den Haag',email:'contact@example.invalid',phone:'0612345678',website:'https://example.invalid',description:'Fictief voor geïsoleerde tests',logoUrl:'',ownerId,stage:'lead',notes:'INTERN-GEHEIM',publicProfile:{name:'Testbedrijf',description:'Publiek profiel',website:'https://example.invalid',logoUrl:''},publicEnabled:false,publicFrom:'',publicUntil:'',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),demo:false});
const business:SponsorBusinessDetails={legalName:'Testbedrijf BV',companyNumber:'12345678',registrationExempt:false,registrationExemptionReason:'',vatNumber:'',vatStatus:'not-applicable',address:'Teststraat 1',postalCode:'1234 AB',city:'Den Haag',country:'NL',contactName:'Test contact',contactFunction:'Directeur',contactEmail:'contact@example.invalid',invoiceEmail:'factuur@example.invalid',phone:'0612345678',confirmedAt:'',confirmedBy:'',updatedAt:''};
