 await command(staff.cookie,'saveSponsorBusinessDetails',[companyId,business,true]);
 for(const [account,roles] of [[signer,['signer']],[marketing,['marketing']],[billing,['billing']]] as const)await command(admin.cookie,'saveMembership',[{id:crypto.randomUUID(),sponsorId:companyId,userId:account.id,roles}]);
