  await assert.rejects(command(staff.cookie,'requestSponsorSigningCode',[agreementId,'club']),/eerst/);
  const at=Date.now();await command(signer.cookie,'requestSponsorSigningCode',[agreementId,'sponsor'],true,companyId);
  const code=(await lastMail('Je ondertekeningscode voor Duindorp SV',at)).text.match(/Je code: (\d{8})/)![1];let [challenge]=await sql`select * from cms_sponsor_signing_challenges where agreement_id=${agreementId} and user_id=${signer.id} and status='pending'`;
  assert.notEqual(challenge.code_hash,code);
