  let current=(await read(staff.cookie)).state.sponsorship!.agreements.find(a=>a.id===agreementId)!;assert.equal(current.status,'awaiting-club-signature');assert.equal(current.signatures[0].name,signer.name);assert.equal(current.signatures[0].ipAddress,'');
  const clubAt=Date.now();await command(staff.cookie,'requestSponsorSigningCode',[agreementId,'club']);const clubCode=(await lastMail('Je ondertekeningscode voor Duindorp SV',clubAt)).text.match(/Je code: (\d{8})/)![1];[challenge]=await sql`select * from cms_sponsor_signing_challenges where agreement_id=${agreementId} and user_id=${staff.id} and status='pending'`;
  const operation=crypto.randomUUID();await command(staff.cookie,'tryCountersignSponsorAgreement',[agreementId,{function:'Sponsorcommissie',consent:true,verificationCode:clubCode,challengeId:challenge.id}],false,'',operation);
  current=(await read(staff.cookie)).state.sponsorship!.agreements.find(a=>a.id===agreementId)!;assert.equal(current.status,'signed');assert.equal(current.signatures.length,2);assert.equal(sponsorSnapshotBytes(current),original);assert.notEqual(current.signatures[0].userId,current.signatures[1].userId);
