  await assert.rejects(command(billing.cookie,'registerSponsorEvent',[eventId,companyId,1],true,companyId),/onvoldoende plaatsen/);
  await assert.rejects(command(signer.cookie,'registerSponsorEvent',[eventId,companyId,4],true,companyId),/onvoldoende plaatsen/);
  event=await staffEvent();assert.equal(event.registrations.length,2);assert.equal(event.registrations.reduce((sum,row)=>sum+row.guests,0),3);assert.equal(event.registrations.find(row=>row.userId===signer.id)!.guests,2,'Rejected updates preserve the existing registration');
