  await assert.rejects(command(signer.cookie,'cancelSponsorEvent',[eventId,otherId],true,companyId),/gekozen sponsorbedrijf/);
  await assert.rejects(command(signer.cookie,'registerSponsorEvent',[eventId,otherId,1],true,otherId),/geen toegang/);
  await command(signer.cookie,'cancelSponsorEvent',[eventId,companyId],true,companyId);event=await staffEvent();assert.equal(event.registrations.length,1);assert.equal(event.registrations[0].userId,marketing.id);assert.equal(event.registrations.reduce((sum,row)=>sum+row.guests,0),1,'Cancelling frees the own two places');
  const race=await Promise.allSettled([command(signer.cookie,'registerSponsorEvent',[eventId,companyId,2],true,companyId),command(billing.cookie,'registerSponsorEvent',[eventId,companyId,2],true,companyId)]);
