  event=await staffEvent();assert.equal(event.registrations.length,2);assert.equal(event.registrations.reduce((sum,row)=>sum+row.guests,0),3);assert.equal(new Set(event.registrations.map(row=>row.userId+'|'+row.sponsorId)).size,event.registrations.length);
